#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <iostream>
#include <random>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>
using Clock=std::chrono::steady_clock;
static inline uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}
static inline uint64_t fnv(const std::string&s,uint64_t h=1469598103934665603ULL){for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct Addr{uint32_t rho,phi,theta,freq;uint16_t coh;uint64_t fp;};
static inline Addr enc(const std::string&k,uint32_t M,uint32_t P,uint32_t T,uint32_t F){uint64_t h1=mix64(fnv(k));uint64_t h2=mix64(h1^0xD6E8FEB86659FD93ULL);uint64_t h3=mix64(h2^0xA5A35625D3E7E5B9ULL);uint64_t h4=mix64(h3^0x94D049BB133111EBULL);uint64_t h5=mix64(h4^0xBF58476D1CE4E5B9ULL);return{uint32_t(h1%M),uint32_t(h2%P),uint32_t(h3%T),uint32_t(h4%F),uint16_t(h5&0xffff),mix64(h1^(h2<<1)^(h3>>1)^h4)};}
enum Mode{RHO_FP=0,RHO_PHI_FP=1,RHO_THETA_FP=2,RHO_F_FP=3,FULL=4,FULL_COH=5};
static inline uint64_t local_key(const Addr&e,Mode m){switch(m){case RHO_FP:return e.fp;case RHO_PHI_FP:return mix64((uint64_t(e.phi)<<32)^e.fp);case RHO_THETA_FP:return mix64((uint64_t(e.theta)<<32)^e.fp);case RHO_F_FP:return mix64((uint64_t(e.freq)<<32)^e.fp);case FULL:return mix64((uint64_t(e.phi)<<40)^(uint64_t(e.theta)<<20)^uint64_t(e.freq)^e.fp);case FULL_COH:return mix64((uint64_t(e.coh)<<48)^(uint64_t(e.phi)<<32)^(uint64_t(e.theta)<<16)^uint64_t(e.freq)^e.fp);}return e.fp;}
class StaticDB{uint32_t M,P,T,F;Mode mode;std::vector<std::unordered_map<uint64_t,uint64_t>>parts;public:StaticDB(uint32_t m,uint32_t p,uint32_t t,uint32_t f,Mode md):M(m),P(p),T(t),F(f),mode(md),parts(m){}void build(const std::vector<std::string>&ks){std::vector<size_t>cnt(M);for(auto&k:ks)cnt[enc(k,M,P,T,F).rho]++;for(size_t i=0;i<M;++i)if(cnt[i])parts[i].reserve(cnt[i]*2+1);for(size_t i=0;i<ks.size();++i){auto e=enc(ks[i],M,P,T,F);parts[e.rho][local_key(e,mode)]=i;}}bool get(const std::string&k,uint64_t&v)const{auto e=enc(k,M,P,T,F);auto&p=parts[e.rho];auto it=p.find(local_key(e,mode));if(it==p.end())return false;v=it->second;return true;}};
struct AdaptivePart{bool compact=true;std::vector<std::pair<uint64_t,uint64_t>>vec;std::unordered_map<uint64_t,uint64_t>map;};
class AdaptiveDB{uint32_t M,P,T,F;Mode mode;size_t threshold;std::vector<AdaptivePart>parts;public:AdaptiveDB(uint32_t m,uint32_t p,uint32_t t,uint32_t f,Mode md,size_t th):M(m),P(p),T(t),F(f),mode(md),threshold(th),parts(m){}void build(const std::vector<std::string>&ks){std::vector<size_t>cnt(M);for(auto&k:ks)cnt[enc(k,M,P,T,F).rho]++;for(size_t i=0;i<M;++i){parts[i].compact=cnt[i]<=threshold;if(parts[i].compact)parts[i].vec.reserve(cnt[i]);else parts[i].map.reserve(cnt[i]*2+1);}for(size_t i=0;i<ks.size();++i){auto e=enc(ks[i],M,P,T,F);auto lk=local_key(e,mode);auto&p=parts[e.rho];if(p.compact)p.vec.emplace_back(lk,i);else p.map[lk]=i;}for(auto&p:parts)if(p.compact)std::sort(p.vec.begin(),p.vec.end(),[](auto&a,auto&b){return a.first<b.first;});}bool get(const std::string&k,uint64_t&v)const{auto e=enc(k,M,P,T,F);auto lk=local_key(e,mode);auto&p=parts[e.rho];if(p.compact){auto it=std::lower_bound(p.vec.begin(),p.vec.end(),lk,[](auto&a,uint64_t x){return a.first<x;});if(it==p.vec.end()||it->first!=lk)return false;v=it->second;return true;}auto it=p.map.find(lk);if(it==p.map.end())return false;v=it->second;return true;}std::pair<size_t,size_t>part_counts()const{size_t c=0,h=0;for(auto&p:parts)(p.compact?c:h)++;return{c,h};}};
template<class DB>std::pair<double,double>bench(DB&db,const std::vector<std::string>&ks,size_t q){std::mt19937_64 r(12345);std::uniform_int_distribution<size_t>d(0,ks.size()-1);std::vector<double>lat;lat.reserve(q);volatile uint64_t sink=0;auto t0=Clock::now();for(size_t i=0;i<q;++i){auto a=Clock::now();uint64_t v=0;db.get(ks[d(r)],v);auto b=Clock::now();sink^=v;lat.push_back(std::chrono::duration<double,std::micro>(b-a).count());}auto t1=Clock::now();std::sort(lat.begin(),lat.end());double us=std::chrono::duration<double,std::micro>(t1-t0).count()/q;double p99=lat[(size_t)(0.99*(lat.size()-1))];return{us,p99};}
const char*mode_name(Mode m){switch(m){case RHO_FP:return"rho+fp";case RHO_PHI_FP:return"rho+phi+fp";case RHO_THETA_FP:return"rho+theta+fp";case RHO_F_FP:return"rho+f+fp";case FULL:return"rho+phi+theta+f+fp";case FULL_COH:return"full+coherence";}return"?";}
int main(int argc,char**argv){size_t N=argc>1?std::stoull(argv[1]):1000000;size_t Q=std::min<size_t>(200000,N);uint32_t M=65536,P=65536,T=65536,F=4096;std::vector<std::string>ks;ks.reserve(N);for(size_t i=0;i<N;++i){char b[48];std::snprintf(b,sizeof(b),"K_%010zu",i);ks.emplace_back(b);}std::cout<<"kind,mode,build_s,lookup_us,p99_us,mops,compact_parts,hash_parts\n";for(Mode m:{RHO_FP,RHO_PHI_FP,RHO_THETA_FP,RHO_F_FP,FULL,FULL_COH}){StaticDB db(M,P,T,F,m);auto a=Clock::now();db.build(ks);auto b=Clock::now();auto[us,p99]=bench(db,ks,Q);std::cout<<"static,"<<mode_name(m)<<','<<std::chrono::duration<double>(b-a).count()<<','<<us<<','<<p99<<','<<(1.0/us)<<",0,"<<M<<"\n";}for(size_t th:{8ul,16ul,24ul,32ul}){AdaptiveDB db(M,P,T,F,FULL_COH,th);auto a=Clock::now();db.build(ks);auto b=Clock::now();auto[us,p99]=bench(db,ks,Q);auto[c,h]=db.part_counts();std::cout<<"adaptive(th="<<th<<"),full+coherence,"<<std::chrono::duration<double>(b-a).count()<<','<<us<<','<<p99<<','<<(1.0/us)<<','<<c<<','<<h<<"\n";}}
